grid-template-columns:1fr 150px;gap:20px;padding:15px 18px;background:var(--surface);border:1px solid var(--line);border-radius:8px;margin-bottom:16px}.task-panel h2{font-size:16px;margin:0 0 8px}.task-panel p{font-size:12px;line-height:1.6;max-width:65ch;margin:0 0 10px;color:var(--muted)}.task-panel canvas{width:150px;height:130px}.task-panel details{font-size:11px;margin-top:9px;color:var(--muted)}.task-panel summary{cursor:pointer;color:var(--accent)}.task-result{font-size:12px!important;color:var(--error)!important;margin-top:10px!important}.task-result.pass{color:var(--green)!important}.task-panel~.studio{height:530px}.reference{padding:38px max(24px,5vw) 70px;max-width:1300px;margin:auto}.reference-intro h1{font-size:32px;font-weight:600;letter-spacing:-.8px;margin:0 0 15px}.reference-intro p{font-size:15px;line-height:1.8;max-width:70ch;color:var(--muted)}.reference-layout{display:grid;grid-template-columns:190px minmax(0,1fr);gap:55px;margin-top:40px}.reference nav{display:flex;flex-direction:column;gap:18px;align-self:start;position:sticky;top:25px;font-size:12px}.reference article{max-width:75ch;font-size:14px;line-height:1.8}.reference h2{font-size:23px;font-weight:600;margin:42px 0 14px;scroll-margin-top:20px}.reference h2:first-child{margin-top:0}.reference h3{font-size:13px;margin:0;color:var(--accent)}.reference p{margin:8px 0 14px}.reference pre{padding:15px;background:var(--soft);border-radius:5px;overflow:auto;font:12px/1.9 monospace}.command-list section{padding:20px 0;border-bottom:1px solid var(--line)}.command-list p{font-size:13px;color:var(--muted)}.command-list pre{margin:0}.toast{position:fixed;left:50%;bottom:28px;transform:translateX(-50%);background:var(--ink);color:var(--surface);padding:12px 18px;border-radius:7px;box-shadow:0 6px 22px #0002;font-size:12px;z-index:100;max-width:calc(100vw - 30px);line-height:1.6}.share-panel{background:var(--surface);padding:18px 24px;border-bottom:1px solid var(--line);display:flex;gap:12px;align-ite