import {createServer} from 'node:http';
import {readFile} from 'node:fs/promises';
import {extname,resolve} from 'node:path';
import {chromium} from '@playwright/test';
import assert from 'node:assert/strict';
import {examples} from '../src/examples.js';
const base=process.env.CHECK_BASE||'/Logomocja/builds/x/';
const server=createServer(async(req,res)=>{try{let path=new URL(req.url,'http://localhost').pathname;if("'!path.startsWith(base))throw 0;let file=resolve('"'dist',decodeURIComponent(path.slice(base.length))||'index.html');if("'!file.startsWith(resolve('"'dist')+'/'))throw 0;let body=await readFile(file);res.setHeader('Content-Type',({'.html':'text/html','.js':'text/javascript','.css':'text/css','.ttf':'font/ttf','.svg':'image/svg+xml'})[extname(file)]||'application/octet-stream');res.end(body);}catch{res.writeHead(404);res.end('404');}});
await new Promise(r=>server.listen(5181,'127.0.0.1',r));
let browser;try{
 browser=await chromium.launch({headless:true,args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1440,height:900}}),errors=[],requests=[];
 page.on('pageerror',e=>errors.push(e.message));page.on('request',r=>requests.push(r.url()));
 await page.goto('http://127.0.0.1:5181'+base);await page.waitForFunction(()=>window.logomocja?.version);await page.evaluate(()=>document.fonts.ready);
 for(let e of examples){let r=await page.evaluate(async e=>{const expected=window.logomocja.run(e.source,e.mode),actual=await window.logomocja.open(e.source,e.mode);return {expected,actual,source:document.querySelector('#source').value};},e);assert.equal(r.actual.error,null,e.name);assert.deepEqual(r.expected,r.actual,e.name);assert.equal(r.source,e.source);}
 await page.reload();await page.waitForFunction(()=>window.logomocja?.version);
 assert.ok(requests.every(url=>url.startsWith('http://127.0.0.1:5181/')),'Runtime requested an external asset');
 await page.context().setOffline(true);
 const offline=await page.evaluate(()=>window.logomocja.open('np 10 gora 90 np 20','3d'));assert.equal(offline.error,null);assert.equal(offline.segments.length,2);
 assert.deepEqual(errors,[]);
 console.log('Static sub-path passed: all 13 open/run results agree; refresh works; only local assets; offline execution works.');
}finally{await browser?.close();server.close();}
EOF
