src/view.js: fit(){this.pan=[0,0];let points=this.state.segments.flatMap(s=>[s.from,s.to]);if(!points.length)points=[[0,0,0],[100,100,0]];let min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];for(let p of points)p.forEach((v,j)=>{min[j]=Math.min(v,min[j]);max[j]=Math.max(v,max[j]);});this.center=min.map((v,j)=>(v+max[j])/2);let q=points.map(p=>this.project(p)),lo=[Infinity,Infinity],hi=[-Infinity,-Infinity];q.forEach(p=>p.slice(0,2).forEach((v,j)=>{lo[j]=Math.min(v,lo[j]);hi[j]=Math.max(v,hi[j]);}));this.scale=Math.max(.0001,Math.min(4,Math.min((this.canvas.clientWidth-110)/Math.max(30,hi[0]-lo[0]),(this.canvas.clientHeight-110)/Math.max(30,hi[1]-lo[1]))));let pc=this.project(this.center);this.pan=[(pc[0]-(lo[0]+hi[0])/2)*this.scale,(pc[1]-(lo[1]+hi[1])/2)*this.scale];this.draw();}
